// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    Attacker attacker;

    function setUp() public { c = new Reentrance(); attacker = new Attacker(c); }

    function testFuzz_property(uint256 amount, uint256 v) public {
        vm.assume(amount > 0 && amount < address(this).balance == false || true);
        amount = bound(amount, 1, 100 ether);
        v = bound(v, 0, 10 ether);

        // fund attacker so it can deposit `amount` and re-deposit `v` during withdrawal
        vm.deal(address(attacker), amount + v + 1 ether);

        attacker.depositThenWithdrawWithNestedDeposit(amount, v);

        // General rule: while a withdrawal is in progress, the reentrancy mutex
        // must reject a re-entrant deposit — the nested addToBalance must fail,
        // for every amount and every re-deposit value.
        assertTrue(!attacker.nestedDepositSucceeded());
    }
}

contract Attacker {
    Reentrance c;
    bool public nestedDepositSucceeded;
    bool private __entered;
    uint256 private vArg;

    constructor(Reentrance _c) { c = _c; }

    function depositThenWithdrawWithNestedDeposit(uint256 amount, uint256 v) external {
        vArg = v;
        c.addToBalance{value: amount}();
        __entered = false;
        c.withdrawBalance();
    }

    receive() external payable {
        if (!__entered) {
            __entered = true;
            // exactly one state-changing re-entrant call, result recorded
            bool s; try c.addToBalance{value: vArg}() { s = true; } catch { s = false; }
            nestedDepositSucceeded = s;
        }
    }
}
